// Берем ВСЁ оригинальное сообщение из Телеграма
const originalItem = $input.first().json;
const userText = originalItem.message?.caption || originalItem.message?.document?.file_name || 'Документ без описания';

return {
  json: {
    ...originalItem, // Оставляем все ID, Chat ID и прочие важные данные
    intent: 'TEST',  // ЖЕСТКО задаем маршрут для финального Switch
    userText: userText
  },
  binary: $input.first().binary // Бережно проносим сам PDF/CSV дальше
};

// Держим индикатор «печатает…» пока агент думает: Telegram гасит его через ~5 сек,
// поэтому обновляем каждые 4.5 сек. ~9 циклов ≈ 40 сек (под лимитом задачи 60 сек).
const token = '8413234787:AAEUX3sgJcD13_N8QTJMJkbBHmwbAXW-bP4';
let chatId;
try { chatId = $('Telegram Trigger').first().json.message.chat.id; } catch (e) {}
if (!chatId) return [{ json: { typing: 'no chat id' } }];
for (let i = 0; i < 9; i++) {
  try {
    await fetch('https://api.telegram.org/bot' + token + '/sendChatAction', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ chat_id: chatId, action: 'typing' }),
    });
  } catch (e) {}
  if (i < 8) await new Promise(r => setTimeout(r, 4500));
}
return [{ json: { typing: 'done', cycles: 9 } }];

const msg = $input.first().json.message || {};
const replied = ((msg.reply_to_message || {}).text) || '';
const m = replied.match(/#(A\d\d)/);
const answer = String(msg.text || '').trim();
const today = new Date(Date.now() + 10*3600*1000).toISOString().slice(0,10);
if (!m || !answer) throw new Error('anamnesis: нет q_id или пустой ответ');
return [{ json: { q_id: m[1], answer, today, chat_id: msg.chat.id } }];

// Capitan — sticky-маршрутизация (Батч 4 хвост).
// Между MergeFinal и Switch. Если пользователь ОТВЕТИЛ реплаем на сообщение бота,
// которое не вопрос анамнеза — это продолжение разговора (обычно с доктором),
// а не новый запрос. Форсим text='SYMPTOM', минуя классификатор, — кроме случаев,
// когда в сообщении явная команда на запись, слэш-команда или прикреплён файл/фото.
// (Static Data в Capitan не работает — id воркфлоу > 21 символа, поэтому опираемся на reply_to_message.)
return $input.all().map(entry => {
  const item = { ...entry.json };
  const msg = item.message || (item.body && item.body.message) || {};
  const rtm = msg.reply_to_message;
  if (rtm && rtm.from && rtm.from.is_bot && !/#A\d{2}/.test(String(rtm.text || rtm.caption || ''))) {
    const t = String(msg.text || msg.caption || '').toLowerCase();
    const explicitLog = /(запиши|занеси|добав[ьи][^.]{0,20}карт|сохрани|зафиксир)/.test(t);
    const explicitCmd = /^\s*\//.test(String(msg.text || ''));
    const hasFile = !!msg.photo || !!msg.document;
    if (!explicitLog && !explicitCmd && !hasFile) {
      item.text = 'SYMPTOM';
      item._sticky_route = 'reply-to-bot → SYMPTOM';
    }
  }
  return { json: item };
});

